describe("CompositeDiscountPolicy", () => {
  it("rejects empty policies array", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow(
      "CompositeDiscountPolicy requires at least one policy",
    );
  });

  describe("sum mode", () => {
    it("sums discounts from each policy against original subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10); // 10% of 1000 = 100
      const p2 = new FixedAmountDiscountPolicy(200);
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      // Sum mode: each sees original subtotal 1000 → 100 + 200 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });

    it("clamps negative child returns to 0 before summing", () => {
      const negativePolicy = {
        computeDiscountCents: () => -100,
      };
      const fixedPolicy = new FixedAmountDiscountPolicy(200);
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, fixedPolicy],
        "sum",
      );
      // -100 clamped to 0, then 0 + 200 = 200
      expect(composite.computeDiscountCents(1000)).toBe(200);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10); // 10% of 1000 = 100
      const p2 = new PercentageDiscountPolicy(10); // 10% of 900 = 90
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      // Chain: 100 + 90 = 190
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("caps each step to remaining amount", () => {
      const p1 = new FixedAmountDiscountPolicy(800);
      const p2 = new FixedAmountDiscountPolicy(500);
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      // Chain: first takes 800, remaining=200, second takes min(500,200)=200
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("ordering matters", () => {
      const tenPercent = new PercentageDiscountPolicy(10);
      const fixed200 = new FixedAmountDiscountPolicy(200);
      const c1 = new CompositeDiscountPolicy([tenPercent, fixed200], "chain");
      const c2 = new CompositeDiscountPolicy([fixed200, tenPercent], "chain");
      // c1: 10% of 1000=100, then fixed 200 from 900 → 300
      // c2: fixed 200 from 1000, then 10% of 800=80 → 280
      expect(c1.computeDiscountCents(1000)).toBe(300);
      expect(c2.computeDiscountCents(1000)).toBe(280);
    });

    it("defaults to sum mode when mode is omitted", () => {
      const p1 = new PercentageDiscountPolicy(10);
      const p2 = new FixedAmountDiscountPolicy(200);
      const composite = new CompositeDiscountPolicy([p1, p2]);
      // Default is sum: 100 + 200 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });
});

