const widget: Product = { id: "w", name: "Widget", unitPriceCents: 1000 };
const gadget: Product = { id: "g", name: "Gadget", unitPriceCents: 2000 };
const heavy: Product = {
  id: "h",
  name: "Heavy",
  unitPriceCents: 500,
  weightGrams: 3000,
};

describe("Cart — line management", () => {
  let cart: Cart;
  beforeEach(() => {
    cart = new Cart();
  });

  it("adds a product and reflects in itemCount", () => {
    cart.add(widget, 3);
    expect(cart.itemCount).toBe(3);
  });

  it("merges quantities when adding the same product twice", () => {
    cart.add(widget, 2);
    cart.add(widget, 3);
    expect(cart.itemCount).toBe(5);
  });

  it("rejects zero quantity", () => {
    expect(() => cart.add(widget, 0)).toThrow(RangeError);
  });

  it("rejects negative quantity", () => {
    expect(() => cart.add(widget, -1)).toThrow(RangeError);
  });

  it("rejects non-integer quantity", () => {
    expect(() => cart.add(widget, 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents", () => {
    const bad: Product = { id: "bad", name: "Bad", unitPriceCents: -1 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("remove returns true for known product and false for unknown", () => {
    cart.add(widget, 1);
    expect(cart.remove("w")).toBe(true);
    expect(cart.remove("w")).toBe(false);
    expect(cart.remove("unknown")).toBe(false);
  });

  it("updateQuantity changes quantity", () => {
    cart.add(widget, 5);
    cart.updateQuantity("w", 2);
    expect(cart.itemCount).toBe(2);
  });

  it("updateQuantity(0) removes the product", () => {
    cart.add(widget, 5);
    cart.updateQuantity("w", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.remove("w")).toBe(false); // already gone
  });

  it("updateQuantity throws for unknown product", () => {
    expect(() => cart.updateQuantity("nope", 1)).toThrow(
      "Product nope is not in the cart",
    );
  });

  it("updateQuantity rejects negative quantity", () => {
    cart.add(widget, 1);
    expect(() => cart.updateQuantity("w", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer quantity", () => {
    cart.add(widget, 1);
    expect(() => cart.updateQuantity("w", 1.5)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    cart.add(widget, 3);
    cart.add(gadget, 2);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns deep copy", () => {
    cart.add(widget, 2);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0]!.product.id).toBe("w");
    expect(snap[0]!.quantity).toBe(2);
    // Mutating snapshot does not affect cart
    (snap[0] as { quantity: number }).quantity = 99;
    expect(cart.itemCount).toBe(2);
  });
});

describe("Cart — totals (pricing pipeline)", () => {
