describe("Cart — async checkout()", () => {
  it("runs without collaborators", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.lines).toHaveLength(1);
  });

  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(widget, 2);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher });
    expect(result.totals.subtotalCents).toBe(3000); // 1500 * 2
    expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
  });

  it("validates inventory and passes on available items", async () => {
    const cart = new Cart();
    cart.add(widget, 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
    expect(inventoryChecker.check).toHaveBeenCalledWith("w", 2);
  });

  it("throws InventoryError when item is unavailable", async () => {
    const cart = new Cart();
    cart.add(widget, 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        reason: "discontinued",
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("w");
      expect(invErr.requested).toBe(5);
      expect(invErr.message).toBe("discontinued");
    }
  });

  it("throws InventoryError on partial-stock denial", async () => {
    const cart = new Cart();
    cart.add(widget, 10);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3, // less than requested 10
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("w");
      expect(invErr.requested).toBe(10);
      expect(invErr.available).toBe(3);
    }
  });

  it("uses asyncTaxProvider for tax calculation", async () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: () => 200,
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: () => 500,
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
      region: "US-CA",
    });
    cart.add(widget, 2); // subtotal=2000, discount=200, discountedSubtotal=1800
    const result = await cart.checkout({ asyncTaxProvider });
    // tax = floor(1800 * 0.1) = 180
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.totals.discountCents).toBe(200);
    expect(result.totals.taxCents).toBe(180);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(1800 + 180 + 500);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
  });

  it("composes priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
    const cart = new Cart({ region: "FR" });
    cart.add(widget, 1);
    cart.add(gadget, 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(1100)  // widget new price
        .mockResolvedValueOnce(2200), // gadget new price
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.2),
    };

    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });

    // subtotal = 1100 + 2200 = 3300
    // no discount → discountedSubtotal = 3300
    // tax = floor(3300 * 0.2) = 660
    // no shipping (FreeShippingCalculator default)
    expect(result.totals.subtotalCents).toBe(3300);
    expect(result.totals.taxCents).toBe(660);
    expect(result.totals.totalCents).toBe(3300 + 660);
    expect(inventoryChecker.check).toHaveBeenCalledTimes(2);
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price service down",
    );
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service down",
    );
  });

  it("does not mutate internal cart state", async () => {
    const cart = new Cart();
    cart.add(widget, 2);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(9999),
    };
    await cart.checkout({ priceFetcher });
    // Cart's internal prices should be unchanged
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(2000); // original price * 2
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [0, 0],
    [1000, 0],
    [999999, 0],
    [-500, 0],
  ])("computeDiscountCents(%i) returns %i", (subtotal, expected) => {
