    ]);

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents(emptyLines, 1000)).toBe(0);
    });

    it("returns 0 when total weight is 0", () => {
      const line: CartLine = {
        product: { id: "a", name: "A", unitPriceCents: 100 },
        quantity: 3,
      };
      expect(calc.computeShippingCents([line], 1000)).toBe(0);
    });

    it("selects the first bracket where weight <= upToGrams", () => {
      expect(calc.computeShippingCents([mkLine("a", 300)], 1000)).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      expect(calc.computeShippingCents([mkLine("a", 500)], 1000)).toBe(300);
      expect(calc.computeShippingCents([mkLine("a", 501)], 1000)).toBe(700);
      expect(calc.computeShippingCents([mkLine("a", 2000)], 1000)).toBe(700);
      expect(calc.computeShippingCents([mkLine("a", 2001)], 1000)).toBe(1200);
    });

    it("uses heaviest bracket cost when exceeding all brackets (no overflow)", () => {
      expect(calc.computeShippingCents([mkLine("a", 10000)], 1000)).toBe(1200);
    });

    it("uses overflowCostCents when provided and exceeding all brackets", () => {
      const withOverflow = new WeightBasedShippingCalculator(
        [
          { upToGrams: 500, costCents: 300 },
          { upToGrams: 2000, costCents: 700 },
        ],
        1500,
      );
      expect(
        withOverflow.computeShippingCents([mkLine("a", 3000)], 1000),
      ).toBe(1500);
    });

    it("sorts brackets regardless of input order", () => {
      const unordered = new WeightBasedShippingCalculator([
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 500, costCents: 300 },
      ]);
      expect(
        unordered.computeShippingCents([mkLine("a", 400)], 1000),
      ).toBe(300);
      expect(
        unordered.computeShippingCents([mkLine("a", 1500)], 1000),
      ).toBe(700);
    });

    it("accounts for quantity in weight calculation", () => {
      // 3 items of 200g = 600g → second bracket (501–2000 → 700)
      expect(
        calc.computeShippingCents([mkLine("a", 200, 3)], 1000),
      ).toBe(700);
    });
  });
});

